import{_ as e,o as s,c as n,ai as i}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"AI Coding","description":"","frontmatter":{},"headers":[],"relativePath":"ai/dev/coding/index.md","filePath":"ai/dev/coding/index.md"}'),r={name:"ai/dev/coding/index.md"};function l(p,a,t,o,d,c){return s(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="ai-coding" tabindex="-1">AI Coding <a class="header-anchor" href="#ai-coding" aria-label="Permalink to “AI Coding”">​</a></h1><blockquote><p>AI Coding 能力总览 + 我的实践入口。不是 Cursor 安装教程。</p></blockquote><p>一句话定位：</p><p><strong>AI Coding 不是让 AI 替代开发，而是把 AI 融入软件工程完整交付流程，在保证架构、质量和可维护性的前提下提升效率。</strong></p><hr><h2 id="我的定位" tabindex="-1">我的定位 <a class="header-anchor" href="#我的定位" aria-label="Permalink to “我的定位”">​</a></h2><ul><li>10 年 Java / 全栈开发经验</li><li>Java / Spring / MySQL / Redis / MQ 等后端工程能力</li><li>正在强化 AI 应用开发能力</li><li>使用 Cursor 等工具参与真实项目开发</li><li>重点盯：AI 生成代码的架构判断、Review、Debug、测试和交付</li></ul><p>核心组合：</p><blockquote><p><strong>工程经验 + AI Coding + AI 应用开发</strong></p></blockquote><p>AI 负责提速；人对需求、架构、质量与最终结果负责。</p><hr><h2 id="什么叫-ai-coding" tabindex="-1">什么叫 AI Coding <a class="header-anchor" href="#什么叫-ai-coding" aria-label="Permalink to “什么叫 AI Coding”">​</a></h2><p>AI Coding = <strong>AI + 软件工程</strong>，不是「会用某个 AI IDE」。</p><p>目标闭环：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>需求理解</span></span>
<span class="line"><span> → 任务拆解</span></span>
<span class="line"><span> → 上下文准备</span></span>
<span class="line"><span> → Prompt / AI 协作</span></span>
<span class="line"><span> → 代码生成</span></span>
<span class="line"><span> → 人工架构判断</span></span>
<span class="line"><span> → Code Review</span></span>
<span class="line"><span> → Debug</span></span>
<span class="line"><span> → 测试</span></span>
<span class="line"><span> → 重构</span></span>
<span class="line"><span> → 交付</span></span>
<span class="line"><span> → 复盘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>工具会换；这条闭环和判断标准才是可迁移的能力。</p><hr><h2 id="ai-coding-工作方式" tabindex="-1">AI Coding 工作方式 <a class="header-anchor" href="#ai-coding-工作方式" aria-label="Permalink to “AI Coding 工作方式”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>需求 → 拆解 → 上下文 → AI 协作 → 实现</span></span>
<span class="line"><span> → Review → 测试 → Debug → 交付 → 复盘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><table tabindex="0"><thead><tr><th>角色</th><th>负责什么</th></tr></thead><tbody><tr><td>AI</td><td>扩大实现与检查的速度和覆盖面（生成、扫描、草稿）</td></tr><tr><td>开发者</td><td>需求理解、架构设计、技术决策、质量控制、最终交付</td></tr></tbody></table><p>原则：先定验收与边界，再让 AI 动手；先分析再修改；关键路径必须人工确认。</p><hr><h2 id="我关注的能力" tabindex="-1">我关注的能力 <a class="header-anchor" href="#我关注的能力" aria-label="Permalink to “我关注的能力”">​</a></h2><p>有内容或真实实践支撑的能力：</p><ul><li>AI 辅助编码</li><li>Prompt / 上下文组织</li><li>AI 生成代码 Review</li><li>AI 辅助 Debug</li><li>AI 辅助重构</li><li>AI 辅助测试</li><li>Java / Spring 后端工程</li><li>全栈业务开发</li><li>AI 应用开发</li></ul><p>不为「看起来完整」空挂栏目；Debug / 测试等会随实践再补页面。</p><hr><h2 id="实践案例" tabindex="-1">实践案例 <a class="header-anchor" href="#实践案例" aria-label="Permalink to “实践案例”">​</a></h2><h3 id="cursor-老项目实战" tabindex="-1"><a href="/my-vitepress-site/ai/ai-programming/cursor-legacy-project.html">Cursor 老项目实战</a> <a class="header-anchor" href="#cursor-老项目实战" aria-label="Permalink to “Cursor 老项目实战”">​</a></h3><p>已有复杂代码上怎么用 AI：上下文、增量修改、风险控制。</p><h3 id="cursor-新项目实战" tabindex="-1"><a href="/my-vitepress-site/ai/ai-programming/cursor-new-project.html">Cursor 新项目实战</a> <a class="header-anchor" href="#cursor-新项目实战" aria-label="Permalink to “Cursor 新项目实战”">​</a></h3><p>0→1：架构设计、模块拆分、Cursor 执行与人工决策。</p><h3 id="ai-code-review" tabindex="-1"><a href="/my-vitepress-site/ai/dev/coding/ai-code-review.html">AI Code Review</a> <a class="header-anchor" href="#ai-code-review" aria-label="Permalink to “AI Code Review”">​</a></h3><p>AI 先扫一轮，人做最终判断；含可复制 Prompt 与防误报流程。</p><h3 id="ai-coding-工作流" tabindex="-1"><a href="/my-vitepress-site/ai/dev/coding/cursor-workflow.html">AI Coding 工作流</a> <a class="header-anchor" href="#ai-coding-工作流" aria-label="Permalink to “AI Coding 工作流”">​</a></h3><p>需求 → 改代码 → 跑通 → Review 的工作流入口（持续完善）。</p><hr><h2 id="与普通-cursor-教程的区别" tabindex="-1">与普通 Cursor 教程的区别 <a class="header-anchor" href="#与普通-cursor-教程的区别" aria-label="Permalink to “与普通 Cursor 教程的区别”">​</a></h2><p>这里不讲「按钮在哪」，而讲：</p><blockquote><p>如何让 AI 参与真实软件工程，同时由开发者控制架构、质量、风险和最终结果。</p></blockquote><p>招聘者若只看工具名，看到的是「会 Cursor」；看这条闭环与案例，看到的是 <strong>AI-assisted software engineering</strong>。</p><hr><h2 id="后续方向" tabindex="-1">后续方向 <a class="header-anchor" href="#后续方向" aria-label="Permalink to “后续方向”">​</a></h2><p>规划说明（尚未单独建页）：</p><ul><li>AI Coding 工程实践沉淀</li><li>AI 生成代码的质量控制</li><li>Debug / 测试专项</li><li>OpenBiz 等项目中的 AI 辅助开发实践</li></ul><p>有真实材料再补页，不造空壳。</p>`,46)])])}const u=e(r,[["render",l]]);export{b as __pageData,u as default};
